#define NASPECTS ((int)(sizeof ASPECTS / sizeof ASPECTS[0]))

static int aspect_matches(const aspect *a, const char *tok) {
    size_t len = strlen(tok);
    if (strcmp(tok, a->name) == 0 || strcmp(tok, a->cat) == 0) return 1;
    /* prefix match on the dotted name, e.g. "sim" matches "sim.plane" */
    if (strncmp(tok, a->name, len) == 0 && a->name[len] == '.') return 1;
    if (strcmp(tok, "all") == 0) return 1;
    if (strcmp(tok, "unit") == 0) return a->is_unit;
    if (strcmp(tok, "cover") == 0) return !a->is_unit;
    return 0;
}

static void usage(void) {
    int i;
    printf(
        "fly99 e2e + visual-coverage suite\n\n"
        "usage: test [flags] [aspect|group ...]\n\n"
        "  no args        run every aspect (units + full visual gallery)\n"
        "  --list         list all aspects and exit\n"
        "  --units        run only correctness aspects (no rendering gallery)\n"
        "  --cover        run only the visual coverage gallery\n"
        "  --fast         accelerate: shrink supersampling/sample counts/resolution\n"
        "  --hq           high quality: bump them (for isolated hero shots)\n"
        "  --help         this text\n\n"
        "aspects/groups (bare tokens select a subset; e.g. `test water views`):\n");
    for (i = 0; i < NASPECTS; ++i)
        printf("  %-14s [%s%s]\n", ASPECTS[i].name, ASPECTS[i].cat,
               ASPECTS[i].is_unit ? "" : ", gallery");
    printf("  groups: unit, cover, all\n");
}

int main(int argc, char **argv) {
    int i, j, ntok = 0, ran = 0;
    int only_units = 0, only_cover = 0, do_list = 0;
    const char *tokens[64];

    for (i = 1; i < argc; ++i) {
        const char *s = argv[i];
        if (strcmp(s, "--help") == 0 || strcmp(s, "-h") == 0) { usage(); return 0; }
        else if (strcmp(s, "--list") == 0) do_list = 1;
        else if (strcmp(s, "--units") == 0) only_units = 1;
        else if (strcmp(s, "--cover") == 0) only_cover = 1;
        else if (strcmp(s, "--fast") == 0) g_fast = 1;
        else if (strcmp(s, "--hq") == 0) g_hq = 1;
        else if (s[0] == '-') { fprintf(stderr, "unknown flag: %s\n", s); usage(); return 2; }
        else if (ntok < (int)(sizeof tokens / sizeof tokens[0])) tokens[ntok++] = s;
    }

    if (do_list) {
        for (i = 0; i < NASPECTS; ++i)
            printf("%-14s %-8s %s\n", ASPECTS[i].name, ASPECTS[i].cat,
                   ASPECTS[i].is_unit ? "unit" : "gallery");
        return 0;
    }

    /* keep stills alongside the build */
#ifdef _WIN32
    if (system("if not exist " FLY_BUILD_DIR "\\shots mkdir " FLY_BUILD_DIR "\\shots") != 0) return 1;
#else
    if (system("mkdir -p " FLY_BUILD_DIR "/shots") != 0) return 1;
#endif

    for (i = 0; i < NASPECTS; ++i) {
        const aspect *a = &ASPECTS[i];
        int sel;
        if (only_units && !a->is_unit) continue;
        if (only_cover && a->is_unit) continue;
        if (ntok == 0) sel = 1;
        else {
            sel = 0;
            for (j = 0; j < ntok; ++j)
                if (aspect_matches(a, tokens[j])) { sel = 1; break; }
        }
        if (!sel) continue;
        printf("[%s] %s\n", a->cat, a->name);
        a->fn();
        ++ran;
    }

    if (ran == 0) {
        fprintf(stderr, "no aspects matched\n");
        return 2;
    }

    /* The gallery is only publishable when all of it ran at the size and
     * sampling the document is shot at: no aspect filter, no --units, no
     * --fast. See write_manifest. */
    write_manifest(!only_units && !g_fast && ntok == 0);
    printf("%d checks, %d failures, %d stills, %d aspects\n",
           fly__tests, fly__fails, g_nshots, ran);
    return fly__fails ? 1 : 0;
}
